import {PHYSIOLOGY_GUIDE_TEXT as old} from './guide-physiology-text.js';
import {p,a,v,table,details} from './guide-markup.js';
import {CARE_GENE_FIELDS} from './care-settings.js';
import {PHYSIOLOGY_DEFAULTS as R} from './physiology-settings.js';
import {CELL_INPUTS,CONTEXT_INPUTS,CANDIDATE_INPUTS,ATTENTION_INPUTS} from './care-brain-layout.js';
const value=(group,key)=>`<span class="guide-value" data-guide-param="${group}.${key}"></span>`;
const care=p('После рождения ребёнок некоторое время находится на родителе. У него собственные энергия, здоровье, пищеварение и рост. Он видит окружение и накапливает личную память; самостоятельных действий и обучения весов пока нет.')
+p('Например, родитель собирает плоды и выбирает «Накормить ребёнка». Пища попадает в желудок ребёнка и затем усваивается с его собственной мощностью. Мозг родителя получает размер и относительное здоровье ребёнка, а не его скрытую энергию или заполненность желудка.')
+details('Срок, нагрузка и самостоятельность',p(`Начальный срок ношения — ${v(CARE_GENE_FIELDS.tCarry.value,'Т')} при стандартном окне роста; выбранное значение основателей: ${value('bodyGenes','tCarry')}. Это отдельный наследуемый ген поведенческой группы. Срок фиксируется при рождении по гену несущего родителя; затем может мутировать независимо от срока роста.`)
+p('Одновременно родитель носит одного ребёнка. До освобождения новое зачатие недоступно. Масса ребёнка прибавляется к массе, определяющей двигательную цену движения; скорость определяется телом родителя. Прибавка не даёт родителю дополнительной ёмкости энергии или здоровья. Оба тела оплачивают своё содержание.')
+p('По окончании срока ребёнок начинает самостоятельную жизнь на той же клетке. При гибели родителя это происходит досрочно, с нынешними запасами и здоровьем ребёнка. Гибель ребёнка освобождает родителя от ношения.'));
export const CARE_GUIDE_TEXT={
 'guide-birth-body':old['guide-birth-body']+'<h4>Ношение родившегося ребёнка</h4>'+care,
 'guide-food-path':old['guide-food-path']+details('Кормление ребёнка',p(`Кормление — отдельный выбор родителя на ${value('physiology','feedSteps')}. Выбирается один вид пищи. В желудок ребёнка переносится минимум запаса родителя и свободного объёма; остаток сохраняется у родителя. Заполненность желудка ребёнка не является входом мозга: безуспешная попытка также занимает время и двигательную цену.`)+p(`Двигательная ставка при опорной массе: ${value('physiology','feedRate')}. Энергия и объём не создаются при передаче; ребёнок усваивает пищу в следующие подшаги. Специальной субъективной награды за заботу нет.`)),
 'guide-actions-body':old['guide-actions-body']+p(`«Накормить ребёнка» длится ${value('physiology','feedSteps')}; доступен родителю с носимым ребёнком и запасом выбранного вида пищи. Несомый ребёнок не выбирает действия. См. ${a('selection','ношение и самостоятельность')}.`),
 'guide-genome-body':old['guide-genome-body'].replace('v18','v19')+p('К генам тела добавлен срок ношения tCarry. Он не заменяет срок беременности tPreg. Формат нового полного мира — v6, плана — v5. Прежние геномы и результаты читаются для анализа, но не запускаются как новые миры.'),
 'guide-brain-structure-body':old['guide-brain-structure-body'].replace(/v18/g,'v19').replace(/<table[\s\S]*?<\/table>/,'')+table('Входы схемы v19',['Блок','Входов'],[['Клетка',v(CELL_INPUTS)],['Контекст',v(CONTEXT_INPUTS)],['Вариант',v(CANDIDATE_INPUTS)],['Диспетчер',v(ATTENTION_INPUTS)]])+p('Четыре собственных признака ухода: наличие ребёнка, его относительный размер и здоровье, доля оставшегося срока. Есть отдельная операция кормления и наблюдения чужого кормления/носимых детей. Самостоятельный выбор начинается после освобождения; накопленная память сохраняется.'),
 'guide-observation-body':old['guide-observation-body']+p('Родитель знает о собственном ношении, сроке и видимом состоянии ребёнка. Ребёнок наблюдает те же локальные клетки со своей личной системой координат. Перемещение родителя обновляет его положение и память без выбранного им действия.'),
 'wiki-saves':old['wiki-saves'].replace('v5','v6').replace('v18','v19').replace('v4','v5')+p('Связь родителя и ребёнка, срок, пища и пассивная память сохраняются. Загрузчик проверяет взаимные ID и совпадение клеток. Автоматического преобразования прежних миров нет: продолжайте их в прежнем выпуске.'),
 'guide-time-body':old['guide-time-body']+p('Переносимый ребёнок перемещается в общей фазе движения вместе с родителем. Поэтому уход от замаха переносит обоих до удара. Освобождение по сроку происходит до остальных завершений; кормление уже освобождённого или погибшего ребёнка не переносит пищу.'),
};
